using System.Collections;
using LittleLeo;
using LittleLeo.Events;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "GenericShop", menuName = "Data/Shop/GenericShop", order = 0)]
public class GenericShop : Reward
{
	private const float openShopDelay = 4.8f;

	private const float openShopDelayLevel4 = 5.1f;

	[Header("Shop Items")]
	[SerializeField]
	private ShopItem[] randomShopItems;

	[SerializeField]
	private int randomShopItemsAmount;

	[Header("Shop Prefab")]
	[SerializeField]
	private GameObject genericShopPrefab;

	[SerializeField]
	private VoidEvent OnOpenShopPanel;

	[SerializeField]
	private GameObject shopScenarioPropsPrefab;

	[SerializeField]
	private Sprite shopScenarioPropsSprite;

	[Header("Assets")]
	[SerializeField]
	private MapHandler mapHandler;

	public ShopItem[] RandomShopItems => randomShopItems;

	public int RandomShopItemsAmount => randomShopItemsAmount;

	public override void GetReward()
	{
		ReferenceSingleton<CoroutineHandler>.Instance.Run(SpawnShopCoroutine());
	}

	private IEnumerator SpawnShopCoroutine()
	{
		ReferenceSingleton<PoolHandler>.Instance.GetObject(shopScenarioPropsPrefab.name).GetComponent<ShopScenarioProps>().Initialize(shopScenarioPropsSprite);
		if (!ReferenceSingleton<GameplayHandler>.Instance.DisableRewardsAnimation)
		{
			yield return new WaitForSeconds(mapHandler.IsOnAstreasHeart ? 5.1f : 4.8f);
		}
		ReferenceSingleton<PoolHandler>.Instance.GetObject(genericShopPrefab.name).GetComponent<ShopPanel>().Initialize(this);
	}
}
